package log

import (
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
)

// The segment-level index lives in a sidecar file next to the segments
// so that Open never has to decode every segment entry when the log has
// grown. It is a derived, rebuildable cache: losing it or finding it
// stale or contradictory only triggers a full rebuild from the segment
// files, never data loss and never an error.
//
// Layout, all integers little-endian:
//
//	header  8 bytes  "BCLIDX" magic (6 bytes) + uint16 version
//	records          one of:
//
//	  committed entry ("E"):
//	    1 byte  'E'
//	    8 bytes segment file number
//	    8 bytes offset of the entry's segment magic
//	    8 bytes length of the whole entry on disk (magic ... crc)
//	    4 bytes disk entry CRC (the checksum stored by the segment)
//	    4 bytes member count m
//	    m × (8-byte seq, 8-byte body offset, 4-byte body length,
//	         8-byte publication generation)
//
//	  hole marker ("H"):
//	    1 byte  'H'
//	    8 bytes segment file number
//	    4 bytes sequence count c
//	    c × 8-byte sequence
//
// The index itself is crash-safe the same way segments are: every
// record carries a trailing CRC of everything before it, and a torn
// final record is discarded as an uncommitted index tail. Because index
// records are appended only after the corresponding segment entry is
// durable, a valid index can never advertise a batch the segments do
// not contain; adoption re-verifies that and every disk entry CRC.
var (
	indexMagic   = []byte{'B', 'C', 'L', 'I', 'D', 'X'}
	indexVersion = uint16(1)

	recEntry = byte('E')
	recHole  = byte('H')
)

// indexEntry is one committed segment entry: either a single batch or a
// whole group, located on disk and carrying every member's index ref.
type indexEntry struct {
	seg    int
	off    int // offset of the entry's segment magic
	length int // total length of the entry on disk, including its CRC
	diskCRC uint32
	members []indexMember
}

type indexMember struct {
	seq    uint64
	off    int // body offset within the segment file
	length int // body length
	gen    uint64
}

type indexHole struct {
	seg  int
	seqs []uint64
}

type parsedIndex struct {
	entries []indexEntry
	holes   []indexHole
}

// readIndexFile parses the sidecar bytes strictly. A truncated final
// record — the remnant of a crash between an index write and its sync —
// is reported as tailLen: the valid prefix length that may be kept.
// Missing bytes are the only tolerated defect; bad framing, an unknown
// version or any checksum mismatch yield errIndexInvalid.
func readIndexFile(data []byte) (p parsedIndex, tailLen int, err error) {
	const headerLen = 8
	if len(data) < headerLen {
		return parsedIndex{}, 0, errIndexInvalid
	}
	if string(data[:6]) != string(indexMagic) {
		return parsedIndex{}, 0, errIndexInvalid
	}
	if binary.LittleEndian.Uint16(data[6:8]) != indexVersion {
		return parsedIndex{}, 0, errIndexInvalid
	}
	pos := headerLen
	for pos < len(data) {
		start := pos
		rest := data[pos:]
		if len(rest) < 6 {
			// type(1) + length(4) + at least a crc byte coming later.
			return p, start, nil
		}
		kind := rest[0]
		bodyLen := int(binary.LittleEndian.Uint32(rest[1:5]))
		if bodyLen < 0 {
			return parsedIndex{}, 0, errIndexInvalid
		}
		// Record = 1 type + 4 length + body + 4 crc.
		total := 6 + bodyLen + 4
		if len(data)-start < total {
			// Any truncation of the last record is a crash tail.
			return p, start, nil
		}
		body := rest[5 : 5+bodyLen]
		crc := binary.LittleEndian.Uint32(rest[5+bodyLen : 9+bodyLen])
		if crc32.ChecksumIEEE(rest[:5+bodyLen]) != crc {
			return parsedIndex{}, 0, errIndexInvalid
		}
		bp := 0
		switch kind {
		case recEntry:
			if bodyLen < 8+8+8+4+4 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e := indexEntry{}
			e.seg = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.off = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.length = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.diskCRC = binary.LittleEndian.Uint32(body[bp : bp+4])
			bp += 4
			m := int(binary.LittleEndian.Uint32(body[bp : bp+4]))
			bp += 4
			if m <= 0 || 28*m != bodyLen-bp {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e.members = make([]indexMember, m)
			for i := 0; i < m; i++ {
				mb := body[bp : bp+28]
				e.members[i] = indexMember{
					seq:    binary.LittleEndian.Uint64(mb[0:8]),
					off:    int(binary.LittleEndian.Uint64(mb[8:16])),
					length: int(binary.LittleEndian.Uint32(mb[16:20])),
					gen:    binary.LittleEndian.Uint64(mb[20:28]),
				}
				bp += 28
			}
			if e.seg <= 0 || e.off < 0 || e.length <= 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			p.entries = append(p.entries, e)
		case recHole:
			if bodyLen < 8+4 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			h := indexHole{}
			h.seg = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			c := int(binary.LittleEndian.Uint32(body[bp : bp+4]))
			bp += 4
			if h.seg <= 0 || c < 0 || 8*c != bodyLen-bp {
				return parsedIndex{}, 0, errIndexInvalid
			}
			h.seqs = make([]uint64, c)
			for i := 0; i < c; i++ {
				h.seqs[i] = binary.LittleEndian.Uint64(body[bp : bp+8])
				bp += 8
			}
			p.holes = append(p.holes, h)
		default:
			return parsedIndex{}, 0, errIndexInvalid
		}
		pos = start + total
	}
	return p, 0, nil
}

var errIndexInvalid = errors.New("log: invalid index sidecar")

// encodeIndexHeader returns the sidecar header.
func encodeIndexHeader() []byte {
	buf := make([]byte, 0, 8)
	buf = append(buf, indexMagic...)
	var tmp [8]byte
	binary.LittleEndian.PutUint16(tmp[:2], indexVersion)
	return append(buf, tmp[:2]...)
}

// finishIndexRecord wraps a record body with its type tag, length and
// trailing checksum.
func finishIndexRecord(kind byte, body []byte) []byte {
	rec := make([]byte, 0, 5+len(body)+4)
	rec = append(rec, kind)
	var tmp [8]byte
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(body)))
	rec = append(rec, tmp[:4]...)
	rec = append(rec, body...)
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(rec))
	return append(rec, tmp[:4]...)
}

// encodeEntryRecord encodes one committed segment entry and its members.
func encodeEntryRecord(e indexEntry) []byte {
	body := make([]byte, 0, 8+8+8+4+4+28*len(e.members))
	var tmp [8]byte
	putU64 := func(v uint64) {
		binary.LittleEndian.PutUint64(tmp[:], v)
		body = append(body, tmp[:]...)
	}
	putU64(uint64(e.seg))
	putU64(uint64(e.off))
	putU64(uint64(e.length))
	binary.LittleEndian.PutUint32(tmp[:4], e.diskCRC)
	body = append(body, tmp[:4]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(e.members)))
	body = append(body, tmp[:4]...)
	for _, m := range e.members {
		putU64(m.seq)
		putU64(uint64(m.off))
		binary.LittleEndian.PutUint32(tmp[:4], uint32(m.length))
		body = append(body, tmp[:4]...)
		putU64(m.gen)
	}
	return finishIndexRecord(recEntry, body)
}

// encodeHoleRecord encodes the durable hole markers found in a segment.
func encodeHoleRecord(h indexHole) []byte {
	body := make([]byte, 0, 8+4+8*len(h.seqs))
	var tmp [8]byte
	binary.LittleEndian.PutUint64(tmp[:], uint64(h.seg))
	body = append(body, tmp[:]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(h.seqs)))
	body = append(body, tmp[:4]...)
	for _, seq := range h.seqs {
		binary.LittleEndian.PutUint64(tmp[:], seq)
		body = append(body, tmp[:]...)
	}
	return finishIndexRecord(recHole, body)
}

// writeIndexSnapshot replaces the sidecar atomically with a full image
// of the recovered log: header, every committed entry in segment order,
// then every segment's holes. The file is fsynced, and its directory is
// fsynced so the rename is itself durable; callers run this after the
// segment files involved have already been synced.
func (l *Log) writeIndexSnapshot(p parsedIndex) error {
	var buf []byte
	buf = append(buf, encodeIndexHeader()...)
	for i := range p.entries {
		buf = append(buf, encodeEntryRecord(p.entries[i])...)
	}
	for i := range p.holes {
		buf = append(buf, encodeHoleRecord(p.holes[i])...)
	}
	tmp := l.indexPath() + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(buf); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, l.indexPath()); err != nil {
		os.Remove(tmp)
		return err
	}
	return syncDir(l.dir)
}

// appendIndexRecord appends one record to the live sidecar after a
// commit's segment entry is durable. With Options.Sync it fsyncs the
// sidecar before returning. An error at any point is returned to the
// caller, which rolls the just-written segment entry back; the record
// is therefore never left advertising a batch unless it committed.
func (l *Log) appendIndexRecord(rec []byte) error {
	if l.idxFile == nil {
		return errIndexInvalid
	}
	if _, err := l.idxFile.Write(rec); err != nil {
		return err
	}
	l.idxSize += len(rec)
	if l.opts.Sync {
		if err := syncFile(l.idxFile); err != nil {
			return fmt.Errorf("%w: %v", ErrSyncFailed, err)
		}
	}
	return nil
}

// truncateIndex rolls the sidecar back to size n after a failed commit,
// mirroring the segment-entry rollback so no uncommitted record remains.
func (l *Log) truncateIndex(n int) {
	if l.idxFile == nil {
		return
	}
	if err := l.idxFile.Truncate(int64(n)); err != nil {
		// Best effort: an untidy sidecar is harmless because Open never
		// trusts it blindly and rebuilds on any contradiction.
		return
	}
	l.idxSize = n
}

// discardIndexTail drops a truncated final record from the sidecar on
// disk (adoption of a crash between the index write and its sync).
func (l *Log) discardIndexTail(n int) error {
	if err := os.Truncate(l.indexPath(), int64(n)); err != nil {
		return err
	}
	l.idxSize = n
	return nil
}

// openIndex creates or opens the live sidecar for append and returns
// its size. A missing file is created; an existing one is assumed to
// have been fully validated (or freshly written) by Open.
func (l *Log) openIndex() error {
	f, err := os.OpenFile(l.indexPath(), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	st, err := f.Stat()
	if err != nil {
		f.Close()
		return err
	}
	l.idxFile = f
	l.idxSize = int(st.Size())
	return nil
}

// indexReader returns one random-access reader over the sidecar bytes.
// Callers must close it. Used only during adoption, for disk-CRC
// verification against the segments.
func (l *Log) readIndexBytes() ([]byte, error) {
	f, err := os.Open(l.indexPath())
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return io.ReadAll(f)
}

