					if m.length <= 0 || m.off+m.length > r.off+r.length-4 {
						return false
					}
					if i == 0 {
						if m.off != bodyStart {
							return false
						}
					} else {
						prev := e.members[i-1]
						if m.off != prev.off+prev.length {
							return false
						}
					}
					if i == len(e.members)-1 && m.off+m.length != r.off+r.length-4 {
						return false
					}
				}
			}
			for _, m := range e.members {
				if m.seq == 0 || seenSeq[m.seq] {
					return false
				}
				seenSeq[m.seq] = true
			}
		case r.hole != nil:
			h := r.hole
			if !bytes.Equal(buf[:4], holeMagic) {
				return false
			}
			if uint32(len(h.seqs)) != binary.LittleEndian.Uint32(buf[4:8]) {
				return false
			}
			if r.length != 8+8*len(h.seqs)+8 {
				return false
			}
