// adoptIndex is the incremental open path. It verifies the sidecar
// against the segment files without decoding record bodies: records must
// tile each referenced segment from offset zero, every on-disk entry
// CRC must match, and member locations must agree with the entry
// headers. Any framing defect, a truncated final record, a version
// mismatch or a contradiction makes it return ok=false and Open rebuilds
// from the segments instead.
//
// The segments may legitimately extend past a verified index prefix —
// the crash window between the segment sync and the index record sync.
// That suffix is parsed incrementally (complete entries get indexed, a
// torn tail of the last segment becomes a hole marker), so adoption
// still costs one small decode rather than a full scan.
func (l *Log) adoptIndex(indices []int, sizes map[int]int) (parsedIndex, bool) {
	data, err := l.readIndexBytes()
	if err != nil {
		return parsedIndex{}, false
	}
	p, tailLen, err := readIndexFile(data)
	if err != nil || tailLen > 0 || len(p.entries) == 0 {
		// Missing/truncated/foreign/empty sidecar: let the full rebuild
		// own these cases.
		return parsedIndex{}, false
	}
	if !l.verifySidecar(p, indices, sizes) {
		return parsedIndex{}, false
	}

	// Verified prefix. Everything past it in the last referenced
	// segment, and any whole segment after it, is incremental suffix.
	lastRef := p.entries[len(p.entries)-1].seg
	if len(p.holes) > 0 {
		if h := p.holes[len(p.holes)-1].seg; h > lastRef {
			lastRef = h
		}
	}
	pos := 0
	for pos < len(indices) && indices[pos] < lastRef {
		pos++
	}
	if pos >= len(indices) || indices[pos] != lastRef {
		return parsedIndex{}, false
	}
	// Offset where suffix begins in the last referenced segment: one
	// past the end of its last record (entry or hole).
	covEnd := 0
	for i := range p.entries {
		if e := &p.entries[i]; e.seg == lastRef && e.off+e.length > covEnd {
			covEnd = e.off + e.length
		}
	}
	for i := range p.holes {
		if h := &p.holes[i]; h.seg == lastRef && h.off+h.length > covEnd {
			covEnd = h.off + h.length
		}
	}

	var extra []diskRecord
	recovered := false
	for si := pos; si < len(indices); si++ {
		n := indices[si]
		raw, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return parsedIndex{}, false
		}
		base := 0
		if si == pos {
			if covEnd > len(raw) {
				return parsedIndex{}, false
			}
			base = covEnd
		}
		batches, markers, tail, perr := parseSegment(raw[base:])
		if perr != nil {
			// A suffix that parses as corruption is tampering, not a
			// sidecar mismatch; but falling through to the rebuild path
			// surfaces the identical ErrCorruptSegment.
			return parsedIndex{}, false
		}
		if tail != nil && si != len(indices)-1 {
			return parsedIndex{}, false
		}
		for k := 0; k < len(batches); {
			diskOff := batches[k].diskOff + base
			j := k + 1
			for j < len(batches) && batches[j].diskOff+base == diskOff {
				j++
			}
			e := indexEntry{
				seg:     n,
				off:     diskOff,
				length:  batches[k].diskLen,
				diskCRC: batches[k].diskCRC,
				members: make([]indexMember, 0, j-k),
			}
			for _, pb := range batches[k:j] {
				e.members = append(e.members, indexMember{
					seq: pb.seq, off: pb.off + base, length: pb.length,
				})
			}
			p.entries = append(p.entries, e)
			extra = append(extra, diskRecord{seg: n, off: diskOff, enc: encodeEntryRecord(e)})
			k = j
		}
		for _, h := range markers {
			ih := indexHole{
				seg: n, off: h.off + base, length: h.length, diskCRC: h.crc,
				seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
			}
			p.holes = append(p.holes, ih)
			extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
		}
		if tail != nil {
			keep := make([]uint64, 0, len(tail.seqs))
			for _, seq := range tail.seqs {
				if seq > 0 {
					keep = append(keep, seq)
				}
			}
			if err := l.rewriteTail(n, base+tail.off, keep); err != nil {
				return parsedIndex{}, false
			}
			recovered = true
			if len(keep) > 0 {
				marker := encodeHoles(keep)
				crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
				ih := indexHole{
					seg: n, off: base + tail.off, length: len(marker), diskCRC: crc,
					seqs: append(make([]uint64, 0, len(keep)), keep...),
				}
				p.holes = append(p.holes, ih)
				extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
			}
		}
	}

	// Persist whatever the suffix added so future opens see it. Doing it
	// through the canonical snapshot writer keeps framing identical to a
	// rebuild (and is itself crash-safe: a crash here leaves a missing
	// or renamed temp, never a torn index).
	_ = recovered
	if len(extra) > 0 {
		if err := l.appendAdoptedSuffix(extra); err != nil {
			return parsedIndex{}, false
		}
	}
	return p, true
}

// appendAdoptedSuffix appends incrementally recovered records to the
// sidecar and fsyncs it. Failure means the caller rebuilds instead.
func (l *Log) appendAdoptedSuffix(recs []diskRecord) error {
	sort.SliceStable(recs, func(i, j int) bool {
		if recs[i].seg != recs[j].seg {
			return recs[i].seg < recs[j].seg
		}
		return recs[i].off < recs[j].off
	})
	f, err := os.OpenFile(l.indexPath(), os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	defer f.Close()
	for _, r := range recs {
		if _, err := f.Write(r.enc); err != nil {
			return err
		}
	}
	return f.Sync()
}

// verifySidecar checks an already-framed parse against the physical
// segments without decoding any record body: referenced segments must
// be a prefix of the directory, records must be strictly ordered and
// tile each segment from offset zero, and every entry's stored CRC must
// still match its on-disk bytes. Member locations and the group member
// count in the entry header are checked as well.
func (l *Log) verifySidecar(p parsedIndex, indices []int, sizes map[int]int) bool {
	if len(indices) == 0 {
		return false
	}
	// Merge entries and holes in file order and walk the physical layout.
	type rec struct {
		seg    int
		off    int
		length int
		crc    uint32
		entry  *indexEntry
		hole   *indexHole
	}
	var recs []rec
	for i := range p.entries {
		recs = append(recs, rec{seg: p.entries[i].seg, off: p.entries[i].off,
			length: p.entries[i].length, crc: p.entries[i].diskCRC, entry: &p.entries[i]})
	}
	for i := range p.holes {
		recs = append(recs, rec{seg: p.holes[i].seg, off: p.holes[i].off,
			length: p.holes[i].length, crc: p.holes[i].diskCRC, hole: &p.holes[i]})
	}
	sort.SliceStable(recs, func(i, j int) bool {
		if recs[i].seg != recs[j].seg {
			return recs[i].seg < recs[j].seg
		}
		return recs[i].off < recs[j].off
	})

	known := make(map[int]bool, len(indices))
	for _, n := range indices {
		known[n] = true
	}
	// The referenced segments must be a prefix of the existing files,
	// each tiled from offset zero with no overlaps or gaps.
	want := 0 // next expected index in indices
	wantOff := 0
	curSeg := -1
	seenSeq := make(map[uint64]bool)
	var f *os.File
	curOpenSeg := -1
	closeFile := func() {
		if f != nil {
			f.Close()
			f = nil
			curOpenSeg = -1
		}
	}
	defer closeFile()

	for _, r := range recs {
		if !known[r.seg] {
			return false
		}
		if r.seg != curSeg {
			// New segment: it must be the next existing one, and every
			// earlier referenced segment was fully covered.
			if curSeg != -1 && wantOff != sizes[curSeg] {
				return false
			}
			for want < len(indices) && indices[want] < r.seg {
				// An existing segment with no index record is a
				// contradiction unless it is past the referenced prefix,
				// handled as suffix; a gap in the middle is not.
				if indices[want] < r.seg && indices[want] != curSeg {
					return false
				}
				want++
			}
			if want >= len(indices) || indices[want] != r.seg {
				return false
			}
			want++
			curSeg = r.seg
			wantOff = 0
			closeFile()
			var err error
			f, err = os.Open(l.segmentPath(r.seg))
			if err != nil {
				return false
			}
			curOpenSeg = r.seg
		}
		if curOpenSeg != r.seg {
			return false
		}
		if r.off != wantOff || r.off < 0 || r.length < 8 || r.off+r.length > sizes[r.seg] {
			return false
		}
		buf := make([]byte, r.length)
		if _, err := f.ReadAt(buf, int64(r.off)); err != nil {
			return false
		}
		if binary.LittleEndian.Uint32(buf[r.length-4:]) != r.crc ||
			crc32.ChecksumIEEE(buf[:r.length-4]) != r.crc {
			return false
		}
		switch {
		case r.entry != nil:
			e := r.entry
			isSingle := bytes.Equal(buf[:4], segmentMagic)
			isGroup := bytes.Equal(buf[:4], groupMagic)
			if !isSingle && !isGroup {
				return false
			}
			if isSingle {
				if len(e.members) != 1 {
					return false
				}
				m := e.members[0]
				if m.off != r.off+4 || m.length != r.length-8 {
					return false
				}
			} else {
				if uint32(len(e.members)) != binary.LittleEndian.Uint32(buf[4:8]) {
					return false
				}
				bodyStart := r.off + 8
				for i, m := range e.members {
					if m.length <= 0 || m.off+m.length > r.off+r.length-4 {
						return false
					}
					if i == 0 {
						if m.off != bodyStart {
							return false
						}
					} else {
						prev := e.members[i-1]
						if m.off != prev.off+prev.length {
							return false
						}
					}
					if i == len(e.members)-1 && m.off+m.length != r.off+r.length-4 {
						return false
					}
				}
			}
			for _, m := range e.members {
				if m.seq == 0 || seenSeq[m.seq] {
					return false
				}
				seenSeq[m.seq] = true
			}
		case r.hole != nil:
			h := r.hole
			if !bytes.Equal(buf[:4], holeMagic) {
				return false
			}
			if uint32(len(h.seqs)) != binary.LittleEndian.Uint32(buf[4:8]) {
				return false
			}
			if r.length != 8+8*len(h.seqs)+8 {
				return false
			}
			for _, seq := range h.seqs {
				if seq == 0 || seenSeq[seq] {
					// A committed seq and a permanent hole cannot share
					// a number; let the rebuild own the judgement call.
					return false
				}
			}
		default:
			return false
		}
		wantOff = r.off + r.length
	}
	return true
