	recs := make([]sidecarRec, 0, len(p.entries)+len(p.holes))
	for i := range p.entries {
		e := &p.entries[i]
		recs = append(recs, sidecarRec{seg: e.seg, off: e.off, length: e.length, crc: e.diskCRC, entry: e})
	}
	for i := range p.holes {
		h := &p.holes[i]
