			// its EOF, and the covered segments must be a prefix with no
			// unindexed segment file in between.
			if prevSeg != -1 && prevEnd != sizes[prevSeg] {
				return 0, 0, false
			}
			if covered >= 0 {
				// expect the next index in the directory listing
				next := indices[0]
				for _, n := range indices {
					if n > prevSeg {
						next = n
						break
					}
				}
				if r.seg != next {
					return 0, 0, false
				}
			} else {
				if r.seg != indices[0] || r.off != 0 {
					return 0, 0, false
				}
			}
			covered++
			_ = covered
			prevSeg = r.seg
			prevEnd = 0
			closeFile()
