			f, err = os.Open(l.segmentPath(r.seg))
			if err != nil {
				return 0, 0, false
			}
			openSeg = r.seg
		}
		if openSeg != r.seg || r.off != prevEnd || r.off+r.length > sizes[r.seg] {
			return 0, 0, false
		}
