		if _, err := f.ReadAt(buf, int64(r.off)); err != nil {
			return 0, 0, false
		}
		if binary.LittleEndian.Uint32(buf[r.length-4:]) != r.crc ||
			crc32.ChecksumIEEE(buf[:r.length-4]) != r.crc {
			return 0, 0, false
		}
		switch {
		case r.entry != nil:
			e := r.entry
