			case bytes.Equal(buf[:4], segmentMagic):
				if len(e.members) != 1 ||
					e.members[0].off != r.off+4 ||
					e.members[0].length != r.length-8 {
					return 0, 0, false
				}
			case bytes.Equal(buf[:4], groupMagic):
				if uint32(len(e.members)) != binary.LittleEndian.Uint32(buf[4:8]) {
					return 0, 0, false
				}
				bodyStart := r.off + 8
				for i, m := range e.members {
					if m.length <= 0 || m.off+m.length > r.off+r.length-4 {
						return 0, 0, false
					}
					if i == 0 {
						if m.off != bodyStart {
							return 0, 0, false
						}
					} else {
