						if m.off != prev.off+prev.length {
							return 0, 0, false
						}
					}
					if i == len(e.members)-1 && m.off+m.length != r.off+r.length-4 {
						return 0, 0, false
					}
				}
			default:
				return 0, 0, false
			}
