				return 0, 0, false
			}
			for _, seq := range h.seqs {
				if seq == 0 || seenSeq[seq] {
					return 0, 0, false
				}
			}
		default:
			return 0, 0, false
		}
		prevEnd = r.off + r.length
	}
	lastSeg := recs[len(recs)-1].seg
	lastEnd := prevEnd

	// The covered segment numbers must be exactly a directory prefix:
	// every file before lastSeg referenced, none after it referenced.
	passed := 0
	for _, n := range indices {
		if n < lastSeg {
			passed++
		}
	}
	// Recs referenced a strictly increasing set starting at indices[0];
	// verify no gap by counting distinct referenced segments.
	refSegs := map[int]bool{}
	for i := range recs {
		refSegs[recs[i].seg] = true
	}
	for _, n := range indices {
		if n < lastSeg && !refSegs[n] {
			return 0, 0, false
		}
	}
	_ = passed
	return lastSeg, lastEnd, true
}

