// adoptIndex is the incremental open path. It verifies the sidecar
// against the segment files without decoding record bodies: records must
// tile each referenced segment from offset zero, every on-disk entry
// CRC must match, and member locations must agree with the entry
// headers. Any framing defect, a truncated final record, a version
// mismatch or a contradiction makes it return ok=false and Open rebuilds
// from the segments instead.
//
// The segments may legitimately extend past a verified index prefix —
// the crash window between the segment sync and the index record sync.
// That suffix is parsed incrementally (complete entries get indexed, a
// torn tail of the last segment becomes a hole marker), so adoption
// still costs one small decode rather than a full scan.
func (l *Log) adoptIndex(indices []int, sizes map[int]int) (parsedIndex, bool) {
	data, err := l.readIndexBytes()
	if err != nil {
		return parsedIndex{}, false
	}
	p, tailLen, err := readIndexFile(data)
	if err != nil || tailLen > 0 || len(p.entries) == 0 {
		// Missing/truncated/foreign/empty sidecar: let the full rebuild
		// own these cases.
		return parsedIndex{}, false
	}
	if !l.verifySidecar(p, indices, sizes) {
		return parsedIndex{}, false
	}

	// Verified prefix. Everything past it in the last referenced
	// segment, and any whole segment after it, is incremental suffix.
	lastRef := p.entries[len(p.entries)-1].seg
	if len(p.holes) > 0 {
		if h := p.holes[len(p.holes)-1].seg; h > lastRef {
			lastRef = h
		}
	}
	pos := 0
	for pos < len(indices) && indices[pos] < lastRef {
		pos++
	}
	if pos >= len(indices) || indices[pos] != lastRef {
		return parsedIndex{}, false
	}
	// Offset where suffix begins in the last referenced segment: one
	// past the end of its last record (entry or hole).
	covEnd := 0
	for i := range p.entries {
		if e := &p.entries[i]; e.seg == lastRef && e.off+e.length > covEnd {
			covEnd = e.off + e.length
		}
	}
	for i := range p.holes {
		if h := &p.holes[i]; h.seg == lastRef && h.off+h.length > covEnd {
			covEnd = h.off + h.length
		}
	}

	var extra []diskRecord
	recovered := false
	for si := pos; si < len(indices); si++ {
		n := indices[si]
		raw, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return parsedIndex{}, false
		}
		base := 0
		if si == pos {
			if covEnd > len(raw) {
				return parsedIndex{}, false
			}
			base = covEnd
		}
		batches, markers, tail, perr := parseSegment(raw[base:])
		if perr != nil {
			// A suffix that parses as corruption is tampering, not a
			// sidecar mismatch; but falling through to the rebuild path
			// surfaces the identical ErrCorruptSegment.
			return parsedIndex{}, false
		}
		if tail != nil && si != len(indices)-1 {
			return parsedIndex{}, false
		}
		for k := 0; k < len(batches); {
			diskOff := batches[k].diskOff + base
			j := k + 1
			for j < len(batches) && batches[j].diskOff+base == diskOff {
				j++
			}
			e := indexEntry{
				seg:     n,
				off:     diskOff,
				length:  batches[k].diskLen,
				diskCRC: batches[k].diskCRC,
				members: make([]indexMember, 0, j-k),
			}
			for _, pb := range batches[k:j] {
				e.members = append(e.members, indexMember{
					seq: pb.seq, off: pb.off + base, length: pb.length,
				})
			}
			p.entries = append(p.entries, e)
			extra = append(extra, diskRecord{seg: n, off: diskOff, enc: encodeEntryRecord(e)})
			k = j
		}
		for _, h := range markers {
			ih := indexHole{
				seg: n, off: h.off + base, length: h.length, diskCRC: h.crc,
				seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
			}
			p.holes = append(p.holes, ih)
			extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
		}
		if tail != nil {
			keep := make([]uint64, 0, len(tail.seqs))
			for _, seq := range tail.seqs {
				if seq > 0 {
					keep = append(keep, seq)
				}
			}
			if err := l.rewriteTail(n, base+tail.off, keep); err != nil {
				return parsedIndex{}, false
			}
