					e.members[0].length != r.length-8 {
					return 0, 0, false
				}
			case bytes.Equal(buf[:4], groupMagic):
				if uint32(len(e.members)) != binary.LittleEndian.Uint32(buf[4:8]) {
					return 0, 0, false
				}
				bodyStart := r.off + 8
				for i, m := range e.members {
					if m.length <= 0 || m.off+m.length > r.off+r.length-4 {
						return 0, 0, false
					}
					if i == 0 {
						if m.off != bodyStart {
							return 0, 0, false
						}
					} else {
						prev := e.members[i-1]
						if m.off != prev.off+prev.length {
							return 0, 0, false
						}
					}
					if i == len(e.members)-1 && m.off+m.length != r.off+r.length-4 {
						return 0, 0, false
					}
				}
			default:
				return 0, 0, false
			}
			for _, m := range e.members {
				if m.seq == 0 || seenSeq[m.seq] {
					return 0, 0, false
				}
