	}
	delete(l.staged, b.seq)
	l.gen++
	l.index[b.seq] = entryRef{seg: l.segIndex, off: off + len(segmentMagic), length: len(entry) - len(segmentMagic) - 4, gen: l.gen}
	l.commitSpan(b.seq, b.seq, 1)
	return b.seq, nil
}

