1	// Package log implements an append-only, batch-commit segmented log.
2	//
3	// A writer stages a batch of opaque records with Append and publishes it
4	// atomically with Commit, or publishes several staged batches atomically
5	// with CommitGroup. Readers only ever see committed batches, in strictly
6	// increasing sequence order starting at 1. Reads locate each batch
7	// through a persistent segment-level index in a sidecar file
8	// ("index.idx"): Open adopts it incrementally, and when it is missing,
9	// truncated, version-mismatched, checksum-bad or contradictory to the
10	// segments, Open rebuilds it from the segment files, so losing the
11	// index never loses data.
12	package log
13	
14	import (
15		"bytes"
16		"encoding/binary"
17		"errors"
18		"fmt"
19		"hash/crc32"
20		"os"
21		"path/filepath"
22		"sort"
23		"strconv"
24		"strings"
25		"sync"
26	)
27	
28	var (
29		// ErrNotCommitted is returned when reading a sequence that has been
30		// staged with Append but not yet committed.
31		ErrNotCommitted = errors.New("log: batch not committed")
32		// ErrUnknownBatch is returned for sequence 0, sequences that were
33		// never reserved, sequences beyond the reserved range, and batches
34		// that have already been committed.
35		ErrUnknownBatch = errors.New("log: unknown batch")
36		// ErrCorruptSegment is returned when a segment file fails validation
37		// while opening or scanning the log.
38		ErrCorruptSegment = errors.New("log: corrupt segment")
39		// ErrInvalidOptions is returned by Open when the options are not
40		// usable, e.g. a non-positive segment capacity.
41		ErrInvalidOptions = errors.New("log: invalid options")
42		// ErrSyncFailed is returned by Commit and CommitGroup when
43		// Options.Sync is set and fsyncing the segment file fails. The
44		// batches stay staged and keep their reserved sequences; committing
45		// them again retries.
46		ErrSyncFailed = errors.New("log: sync failed")
47	)
48	
49	var errClosed = errors.New("log: closed")
50	
51	// syncFile fsyncs a segment file. It is a variable so tests can
52	// simulate sync failures.
53	var syncFile = func(f *os.File) error { return f.Sync() }
54	
55	// Options configures a Log opened with Open.
56	type Options struct {
57		// SegmentBytes is the capacity of one segment file in bytes. Once a
58		// non-empty segment would exceed it, the log rolls to a new segment.
59		// A single batch or group larger than the capacity occupies its own
60		// segment. Must be positive.
61		SegmentBytes int
62		// Sync makes Commit and CommitGroup fsync the segment file before
63		// returning, so a returned commit is durable.
64		Sync bool
65	}
66	
67	// Batch is a group of records identified by a single sequence number.
68	// A Batch returned by Append is staged; after Commit or CommitGroup it
69	// is readable.
70	type Batch struct {
71		seq     uint64
72		records [][]byte
73		owner   *Log
74	}
75	
76	// Seq returns the sequence number reserved for the batch.
77	func (b Batch) Seq() uint64 { return b.seq }
78	
79	// Records returns a copy of the batch's records.
80	func (b Batch) Records() [][]byte { return copyRecords(b.records) }
81	
82	// Segment describes one segment file by the committed sequences it holds.
83	type Segment struct {
84		FirstSeq uint64
85		LastSeq  uint64
86	}
87	
88	// entryRef locates one committed batch body inside a segment file. The
89	// persistent index sidecar stores the same locations; its loss or
90	// invalidation is always safe because Open rebuilds it from the
91	// segments. gen is the publication generation of the commit that
92	// published the batch; every member of a group commit shares one gen,
93	// which lets a streaming replay snapshot see the whole group or none of
94	// it.
95	type entryRef struct {
96		seg    int // segment file number
97		off    int // offset of the batch body within the segment
98		length int // length of the batch body
99		gen    uint64
100	}
101	
102	// Log is an append-only batch-commit log stored in a directory of
103	// segment files. It is safe for concurrent use, but the writer side is
104	// expected to be a single goroutine (see README Limits).
105	//
106	// The read and write paths are decoupled: writers take mu exclusively,
107	// while readers hold it only for the brief index and staged-state
108	// lookups. Segment file reads, decoding and user callbacks happen
109	// outside the lock, so a slow reader or a long replay never blocks a
110	// committing writer.
111	type Log struct {
112		dir  string
113		opts Options
114	
115		// mu guards the mutable index and write state below. Readers never
116		// hold it across file I/O, decoding or callbacks.
117		mu         sync.RWMutex
118		file       *os.File // current segment, nil until first write
119		fileSize   int
120		idxFile    *os.File // index sidecar, opened for append
121		idxSize    int
122		segIndex   int // index of the current segment file, 0 = none yet
123		curBatches int // committed batches in the current segment
124		nextSeq    uint64
125		staged     map[uint64][][]byte
126		index      map[uint64]entryRef
127		segs       []Segment // segments holding at least one committed batch
128		gen        uint64    // publication generation of the last commit
129		closed     bool
130	}
131	
132	// Open opens the log in dir, creating the directory if needed. The
133	// committed set is taken from the persistent index sidecar when it can
134	// be adopted incrementally; if the sidecar is missing, truncated, from
135	// another version, checksum-bad or contradictory to the segment files,
136	// Open transparently rebuilds it by scanning the segments once. Either
137	// path yields identical reads, replays, segment listings and errors.
138	//
139	// A half-written tail of the last segment — the remnant of a crash
140	// mid-write — is replaced by a durable hole marker without error and
141	// its reserved sequences stay permanent holes across reopens; any other
142	// inconsistency is ErrCorruptSegment.
143	func Open(dir string, opts Options) (*Log, error) {
144		if opts.SegmentBytes <= 0 {
145			return nil, ErrInvalidOptions
146		}
147		if err := os.MkdirAll(dir, 0o755); err != nil {
148			return nil, err
149		}
150		entries, err := os.ReadDir(dir)
151		if err != nil {
152			return nil, err
153		}
154		var indices []int
155		for _, e := range entries {
156			if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
157				continue
158			}
159			n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
160			if err != nil {
161				continue
162			}
163			indices = append(indices, n)
164		}
165		sort.Ints(indices)
166	
167		l := &Log{
168			dir:     dir,
169			opts:    opts,
170			nextSeq: 1,
171			staged:  make(map[uint64][][]byte),
172			index:   make(map[uint64]entryRef),
173		}
174	
175		// Segment sizes are all the segment metadata adoption needs; the
176		// contents are touched only by the cheap CRC pass, never decoded
177		// entry by entry.
178		sizes := make(map[int]int, len(indices))
179		for _, n := range indices {
180			st, err := os.Stat(l.segmentPath(n))
181			if err != nil {
182				return nil, err
183			}
184			sizes[n] = int(st.Size())
185		}
186	
187		snapshot, ok := l.adoptIndex(indices, sizes)
188		if !ok {
189			snapshot, err = l.rebuildFromSegments(indices)
190			if err != nil {
191				return nil, err
192			}
193		}
194		sortIndexSnapshot(&snapshot)
195		l.installSnapshot(snapshot, indices)
196	
197		if len(indices) > 0 {
198			l.segIndex = indices[len(indices)-1]
199			if err := l.openCurrent(); err != nil {
200				return nil, err
201			}
202		}
203		if err := l.openIndex(); err != nil {
204			return nil, err
205		}
206		return l, nil
207	}
208	
209	// installSnapshot populates the in-memory index, segment listing, staged
210	// holes and next-sequence counter from an adopted or rebuilt snapshot.
211	// Both open paths funnel through here so their observable state is
212	// identical. Entries must be ordered by (segment, disk offset); each
213	// entry (a single commit or one group) gets one publication generation.
214	func (l *Log) installSnapshot(p parsedIndex, indices []int) {
215		for i := range p.entries {
216			e := &p.entries[i]
217			l.gen++
218			for _, m := range e.members {
219				l.index[m.seq] = entryRef{seg: e.seg, off: m.off, length: m.length, gen: l.gen}
220				if m.seq >= l.nextSeq {
221					l.nextSeq = m.seq + 1
222				}
223			}
224		}
225		// Segment listing: one entry per physical segment that holds at
226		// least one committed batch.
227		segSeen := make(map[int]int)
228		for i := range p.entries {
229			e := &p.entries[i]
230			var first, last uint64
231			for j, m := range e.members {
232				if j == 0 {
233					first, last = m.seq, m.seq
234				}
235				if m.seq < first {
236					first = m.seq
237				}
238				if m.seq > last {
239					last = m.seq
240				}
241			}
242			if idx, known := segSeen[e.seg]; known {
243				if first < l.segs[idx].FirstSeq {
244					l.segs[idx].FirstSeq = first
245				}
246				if last > l.segs[idx].LastSeq {
247					l.segs[idx].LastSeq = last
248				}
249			} else {
250				segSeen[e.seg] = len(l.segs)
251				l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
252			}
253		}
254		// Holes reserve sequences permanently: they read as staged (never
255		// committed) and are never reused, across any number of reopens.
256		for i := range p.holes {
257			for _, seq := range p.holes[i].seqs {
258				if seq == 0 {
259					continue
260				}
261				if _, committed := l.index[seq]; !committed {
262					l.staged[seq] = nil
263				}
264				if seq >= l.nextSeq {
265					l.nextSeq = seq + 1
266				}
267			}
268		}
269		if len(indices) > 0 {
270			last := indices[len(indices)-1]
271			l.curBatches = 0
272			for i := range p.entries {
273				if p.entries[i].seg == last {
274					l.curBatches += len(p.entries[i].members)
275				}
276			}
277		}
278	}
279	
280	// sortIndexSnapshot orders a snapshot's records by (segment, offset),
281	// the canonical on-disk and publication order.
282	func sortIndexSnapshot(p *parsedIndex) {
283		sort.SliceStable(p.entries, func(i, j int) bool {
284			if p.entries[i].seg != p.entries[j].seg {
285				return p.entries[i].seg < p.entries[j].seg
286			}
287			return p.entries[i].off < p.entries[j].off
288		})
289		sort.SliceStable(p.holes, func(i, j int) bool {
290			if p.holes[i].seg != p.holes[j].seg {
291				return p.holes[i].seg < p.holes[j].seg
292			}
293			return p.holes[i].off < p.holes[j].off
294		})
295	}
296	
297	// adoptIndex is the incremental open path. It verifies the sidecar
298	// against the segment files without decoding record bodies: its records
299	// must tile a prefix of the segment files from offset zero, every
300	// on-disk CRC must match, and member locations must agree with the entry
301	// headers. Any framing defect, a truncated final record, a version
302	// mismatch or a contradiction makes it return ok=false and Open rebuilds
303	// from the segments instead.
304	//
305	// The segments may legitimately extend past a verified index — the
306	// crash window between the segment sync and the index record sync. That
307	// suffix (extra bytes of the last covered segment, plus any whole later
308	// segment) is parsed incrementally: complete entries get indexed, a
309	// torn tail of the last segment becomes a hole marker, so adoption
310	// still costs one small decode rather than a full scan.
311	func (l *Log) adoptIndex(indices []int, sizes map[int]int) (parsedIndex, bool) {
312		if len(indices) == 0 {
313			// No segments: nothing to index; openIndex creates the sidecar
314			// lazily with its header when the first commit lands.
315			return parsedIndex{}, true
316		}
317		data, err := l.readIndexBytes()
318		if err != nil {
319			return parsedIndex{}, false
320		}
321		p, tailLen, err := readIndexFile(data)
322		if err != nil || tailLen > 0 {
323			// Missing/truncated/foreign sidecar: the rebuild path owns
324			// these cases.
325			return parsedIndex{}, false
326		}
327		if len(p.entries) == 0 && len(p.holes) == 0 {
328			// A recordless sidecar is valid only when every segment is
329			// empty; otherwise the sidecar is simply behind and the
330			// rebuild path catches up.
331			for _, n := range indices {
332				if sizes[n] != 0 {
333					return parsedIndex{}, false
334				}
335			}
336			return p, true
337		}
338		covered, covEnd, ok := l.verifySidecar(p, indices, sizes)
339		if !ok {
340			return parsedIndex{}, false
341		}
342	
343		// Everything at or after covered is unverified suffix: the unindexed
344		// tail bytes of segment covered, then every whole later segment.
345		pos := 0
346		for pos < len(indices) && indices[pos] < covered {
347			pos++
348		}
349		var extra []diskRecord
350		for si := pos; si < len(indices); si++ {
351			n := indices[si]
352			raw, err := os.ReadFile(l.segmentPath(n))
353			if err != nil {
354				return parsedIndex{}, false
355			}
356			base := 0
357			if n == covered {
358				if covEnd > len(raw) {
359					return parsedIndex{}, false
360				}
361				base = covEnd
362			}
363			batches, markers, tail, perr := parseSegment(raw[base:])
364			if perr != nil {
365				// Tampering in the suffix surfaces through the rebuild path
366				// with the identical ErrCorruptSegment.
367				return parsedIndex{}, false
368			}
369			if tail != nil && si != len(indices)-1 {
370				return parsedIndex{}, false
371			}
372			for k := 0; k < len(batches); {
373				diskOff := batches[k].diskOff + base
374				j := k + 1
375				for j < len(batches) && batches[j].diskOff+base == diskOff {
376					j++
377				}
378				e := indexEntry{
379					seg:     n,
380					off:     diskOff,
381					length:  batches[k].diskLen,
382					diskCRC: batches[k].diskCRC,
383					members: make([]indexMember, 0, j-k),
384				}
385				for _, pb := range batches[k:j] {
386					e.members = append(e.members, indexMember{
387						seq: pb.seq, off: pb.off + base, length: pb.length,
388					})
389				}
390				p.entries = append(p.entries, e)
391				extra = append(extra, diskRecord{seg: n, off: diskOff, enc: encodeEntryRecord(e)})
392				k = j
393			}
394			for _, h := range markers {
395				ih := indexHole{
396					seg: n, off: h.off + base, length: h.length, diskCRC: h.crc,
397					seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
398				}
399				p.holes = append(p.holes, ih)
400				extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
401			}
402			if tail != nil {
403				keep := make([]uint64, 0, len(tail.seqs))
404				for _, seq := range tail.seqs {
405					if seq > 0 {
406						keep = append(keep, seq)
407					}
408				}
409				if err := l.rewriteTail(n, base+tail.off, keep); err != nil {
410					return parsedIndex{}, false
411				}
412				if len(keep) > 0 {
413					marker := encodeHoles(keep)
414					crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
415					ih := indexHole{
416						seg: n, off: base + tail.off, length: len(marker), diskCRC: crc,
417						seqs: append(make([]uint64, 0, len(keep)), keep...),
418					}
419					p.holes = append(p.holes, ih)
420					extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
421				}
422			}
423		}
424	
425		// Persist the incrementally recovered records so later opens adopt
426		// them too. A crash during this append leaves a torn final index
427		// record, and the next open simply rebuilds.
428		if len(extra) > 0 {
429			if err := l.appendAdoptedSuffix(extra); err != nil {
430				return parsedIndex{}, false
431			}
432		}
433		return p, true
434	}
435	
436	// appendAdoptedSuffix appends incrementally recovered records to the
437	// sidecar and fsyncs it. Failure means the caller rebuilds instead.
438	func (l *Log) appendAdoptedSuffix(recs []diskRecord) error {
439		sort.SliceStable(recs, func(i, j int) bool {
440			if recs[i].seg != recs[j].seg {
441				return recs[i].seg < recs[j].seg
442			}
443			return recs[i].off < recs[j].off
444		})
445		f, err := os.OpenFile(l.indexPath(), os.O_WRONLY|os.O_APPEND, 0o644)
446		if err != nil {
447			return err
448		}
449		defer f.Close()
450		for _, r := range recs {
451			if _, err := f.Write(r.enc); err != nil {
452				return err
453			}
454		}
455		return f.Sync()
456	}
457	
458	// sidecarRec is one physical record the index claims.
459	type sidecarRec struct {
460		seg    int
461		off    int
462		length int
463		crc    uint32
464		entry  *indexEntry
465		hole   *indexHole
466	}
467	
468	// verifySidecar checks an already-framed parse against the physical
469	// segments without decoding any record body. It returns the last segment
470	// the index covers and the offset immediately after its records there.
471	//
472	// The covered segments must be a prefix of the segment files in the
473	// directory; within each one records must be strictly ordered, start at
474	// offset zero and tile without gaps or overlap. Every covered segment
475	// except the last must end exactly at the file size (nothing
476	// unindexed); the last one may stop short, leaving a suffix for
477	// incremental parsing. Every stored disk CRC is recomputed, and entry
478	// headers (magic and group membership layout) are checked.
479	func (l *Log) verifySidecar(p parsedIndex, indices []int, sizes map[int]int) (coveredSeg int, coveredEnd int, ok bool) {
480		if len(indices) == 0 {
481			return 0, 0, false
482		}
483		recs := make([]sidecarRec, 0, len(p.entries)+len(p.holes))
484		for i := range p.entries {
485			e := &p.entries[i]
486			recs = append(recs, sidecarRec{seg: e.seg, off: e.off, length: e.length, crc: e.diskCRC, entry: e})
487		}
488		for i := range p.holes {
489			h := &p.holes[i]
490			recs = append(recs, sidecarRec{seg: h.seg, off: h.off, length: h.length, crc: h.diskCRC, hole: h})
491		}
492		sort.SliceStable(recs, func(i, j int) bool {
493			if recs[i].seg != recs[j].seg {
494				return recs[i].seg < recs[j].seg
495			}
496			return recs[i].off < recs[j].off
497		})
498	
499		known := make(map[int]bool, len(indices))
500		for _, n := range indices {
501			known[n] = true
502		}
503		covered := false
504		seenSeq := make(map[uint64]bool)
505		var f *os.File
506		openSeg := -1
507		closeFile := func() {
508			if f != nil {
509				f.Close()
510				f = nil
511				openSeg = -1
512			}
513		}
514		defer closeFile()
515	
516		prevSeg, prevEnd := -1, 0
517		for i := range recs {
518			r := &recs[i]
519			if !known[r.seg] || r.off < 0 || r.length < 8 {
520				return 0, 0, false
521			}
522			if r.seg != prevSeg {
523				// A new covered segment: the previous one must be tiled to
524				// its EOF, and the covered segments must be a prefix with no
525				// unindexed segment file in between.
526				if prevSeg != -1 && prevEnd != sizes[prevSeg] {
527					return 0, 0, false
528				}
529				if covered {
530					next := 0
531					found := false
532					for _, n := range indices {
533						if n > prevSeg {
534							next, found = n, true
535							break
536						}
537					}
538					if !found || r.seg != next || r.off != 0 {
539						return 0, 0, false
540					}
541				} else {
542					if r.seg != indices[0] || r.off != 0 {
543						return 0, 0, false
544					}
545				}
546				covered = true
547				prevSeg = r.seg
548				prevEnd = 0
549				closeFile()
550				var err error
551				f, err = os.Open(l.segmentPath(r.seg))
552				if err != nil {
553					return 0, 0, false
554				}
555				openSeg = r.seg
556			}
557			if openSeg != r.seg || r.off != prevEnd || r.off+r.length > sizes[r.seg] {
558				return 0, 0, false
559			}
560			buf := make([]byte, r.length)
561			if _, err := f.ReadAt(buf, int64(r.off)); err != nil {
562				return 0, 0, false
563			}
564			if binary.LittleEndian.Uint32(buf[r.length-4:]) != r.crc ||
565				crc32.ChecksumIEEE(buf[:r.length-4]) != r.crc {
566				return 0, 0, false
567			}
568			switch {
569			case r.entry != nil:
570				e := r.entry
571				switch {
572				case bytes.Equal(buf[:4], segmentMagic):
573					if len(e.members) != 1 ||
574						e.members[0].seq != binary.LittleEndian.Uint64(buf[4:12]) ||
575						e.members[0].off != r.off+4 ||
576						e.members[0].length != r.length-8 {
577						return 0, 0, false
578					}
579				case bytes.Equal(buf[:4], groupMagic):
580					if uint32(len(e.members)) != binary.LittleEndian.Uint32(buf[4:8]) {
581						return 0, 0, false
582					}
583					bodyStart := r.off + 8
584					for i, m := range e.members {
585						if m.length <= 0 || m.off+m.length > r.off+r.length-4 {
586							return 0, 0, false
587						}
588						// The member's stored sequence must agree with the
589						// index record.
590						if m.seq != binary.LittleEndian.Uint64(buf[m.off-r.off:m.off-r.off+8]) {
591							return 0, 0, false
592						}
593						if i == 0 {
594							if m.off != bodyStart {
595								return 0, 0, false
596							}
597						} else {
598							prev := e.members[i-1]
599							if m.off != prev.off+prev.length {
600								return 0, 0, false
601							}
602						}
603						if i == len(e.members)-1 && m.off+m.length != r.off+r.length-4 {
604							return 0, 0, false
605						}
606					}
607				default:
608					return 0, 0, false
609				}
610				for _, m := range e.members {
611					if m.seq == 0 || seenSeq[m.seq] {
612						return 0, 0, false
613					}
614					seenSeq[m.seq] = true
615				}
616			case r.hole != nil:
617				h := r.hole
618				if !bytes.Equal(buf[:4], holeMagic) ||
619					uint32(len(h.seqs)) != binary.LittleEndian.Uint32(buf[4:8]) ||
620					r.length != 4+4+8*len(h.seqs)+4 {
621					return 0, 0, false
622				}
623				for _, seq := range h.seqs {
624					if seq == 0 || seenSeq[seq] {
625						return 0, 0, false
626					}
627				}
628			default:
629				return 0, 0, false
630			}
631			prevEnd = r.off + r.length
632		}
633		lastSeg := recs[len(recs)-1].seg
634		lastEnd := prevEnd
635	
636		// Every segment file before the last covered one must carry at
637		// least one index record (no unindexed segment in the middle).
638		refSegs := map[int]bool{}
639		for i := range recs {
640			refSegs[recs[i].seg] = true
641		}
642		for _, n := range indices {
643			if n < lastSeg && !refSegs[n] {
644				return 0, 0, false
645			}
646		}
647		return lastSeg, lastEnd, true
648	}
649	
650	// segment exactly as a historical open did, recovers a torn tail of the
651	// last segment into a durable hole marker, and finally persists a fresh
652	// index snapshot. Tampering anywhere but the last segment's tail stays
653	// ErrCorruptSegment.
654	func (l *Log) rebuildFromSegments(indices []int) (parsedIndex, error) {
655		var p parsedIndex
656		for i, n := range indices {
657			data, err := os.ReadFile(l.segmentPath(n))
658			if err != nil {
659				return parsedIndex{}, err
660			}
661			batches, markers, tail, err := parseSegment(data)
662			if err != nil {
663				return parsedIndex{}, err
664			}
665			if tail != nil && i != len(indices)-1 {
666				// A half-written tail is a crash remnant only in the last
667				// segment; anywhere else it is tampering.
668				return parsedIndex{}, ErrCorruptSegment
669			}
670			for k := 0; k < len(batches); {
671				// Members of one group entry share diskOff; a single commit
672				// is an entry with one member.
673				diskOff := batches[k].diskOff
674				j := k + 1
675				for j < len(batches) && batches[j].diskOff == diskOff {
676					j++
677				}
678				e := indexEntry{
679					seg:     n,
680					off:     batches[k].diskOff,
681					length:  batches[k].diskLen,
682					diskCRC: batches[k].diskCRC,
683					members: make([]indexMember, 0, j-k),
684				}
685				for _, pb := range batches[k:j] {
686					e.members = append(e.members, indexMember{seq: pb.seq, off: pb.off, length: pb.length})
687				}
688				p.entries = append(p.entries, e)
689				k = j
690			}
691			for _, h := range markers {
692				p.holes = append(p.holes, indexHole{
693					seg: n, off: h.off, length: h.length, diskCRC: h.crc,
694					seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
695				})
696			}
697			if tail != nil {
698				// Replace the torn entry with a durable hole marker so its
699				// reserved sequences stay permanent holes, then index the
700				// replacement marker as part of the fresh snapshot.
701				keep := make([]uint64, 0, len(tail.seqs))
702				for _, seq := range tail.seqs {
703					if seq > 0 {
704						keep = append(keep, seq)
705					}
706				}
707				if err := l.rewriteTail(n, tail.off, keep); err != nil {
708					return parsedIndex{}, err
709				}
710				if len(keep) > 0 {
711					marker := encodeHoles(keep)
712					crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
713					p.holes = append(p.holes, indexHole{
714						seg: n, off: tail.off, length: len(marker), diskCRC: crc,
715						seqs: append(make([]uint64, 0, len(keep)), keep...),
716					})
717				}
718			}
719		}
720		sortIndexSnapshot(&p)
721		if err := l.writeIndexSnapshot(p); err != nil {
722			return parsedIndex{}, err
723		}
724		return p, nil
725	}
726	
727	// Append stages a batch of records and reserves the next sequence number
728	// for it. The batch becomes readable only after Commit or CommitGroup.
729	func (l *Log) Append(records [][]byte) (Batch, error) {
730		l.mu.Lock()
731		defer l.mu.Unlock()
732		if l.closed {
733			return Batch{}, errClosed
734		}
735		recs := copyRecords(records)
736		seq := l.nextSeq
737		l.nextSeq++
738		l.staged[seq] = recs
739		return Batch{seq: seq, records: recs, owner: l}, nil
740	}
741	
742	// Commit makes a staged batch durable and readable, and returns its
743	// reserved sequence number. Committing a batch that is not staged —
744	// including one already committed — returns ErrUnknownBatch. With
745	// Options.Sync a returned commit is durable: the segment entry and the
746	// index sidecar record are both synced, one fsync each. If either
747	// fsync fails Commit returns ErrSyncFailed, rolls both files back and
748	// the batch stays staged, keeping its reserved sequence for a retry
749	// that cannot produce a duplicate entry.
750	func (l *Log) Commit(b Batch) (uint64, error) {
751		l.mu.Lock()
752		defer l.mu.Unlock()
753		if l.closed {
754			return 0, errClosed
755		}
756		recs, ok := l.staged[b.seq]
757		if !ok || b.owner != l {
758			return 0, ErrUnknownBatch
759		}
760		entry := encodeBatch(b.seq, recs)
761		idxBefore := l.idxSize
762		off, err := l.writeEntry(entry)
763		if err != nil {
764			return 0, err
765		}
766		if l.opts.Sync {
767			if err := syncFile(l.file); err != nil {
768				// The batch stays staged and keeps its reserved sequence;
769				// a later Commit retries. Drop the un-synced entry so the
770				// retry cannot duplicate it on disk.
771				l.rollbackEntry(off, idxBefore)
772				return 0, fmt.Errorf("%w: %v", ErrSyncFailed, err)
773			}
774		}
775		rec := encodeEntryRecord(indexEntry{
776			seg:     l.segIndex,
777			off:     off,
778			length:  len(entry),
779			diskCRC: binary.LittleEndian.Uint32(entry[len(entry)-4:]),
780			members: []indexMember{{
781				seq: b.seq, off: off + len(segmentMagic),
782				length: len(entry) - len(segmentMagic) - 4,
783			}},
784		})
785		if err := l.appendIndexRecord(rec); err != nil {
786			// Index write/fsync failed: the commit is not published. Roll
787			// the index record and the segment entry both back so a retry
788			// republishes exactly once.
789			l.rollbackEntry(off, idxBefore)
790			return 0, err
791		}
792		delete(l.staged, b.seq)
793		l.gen++
794		l.index[b.seq] = entryRef{seg: l.segIndex, off: off + len(segmentMagic), length: len(entry) - len(segmentMagic) - 4, gen: l.gen}
795		l.commitSpan(b.seq, b.seq, 1)
796		return b.seq, nil
797	}
798	
799	// CommitGroup makes several staged batches durable and readable as one
800	// atomic unit: a single segment write and, with Options.Sync, a single
801	// segment fsync covering the whole group, followed by one index record
802	// synced once. Each batch keeps the sequence it reserved at Append, and
803	// the batches become visible in that reserved order — the merge never
804	// reorders them. If any batch is not staged — including one already
805	// committed — nothing is written and the error is ErrUnknownBatch. If
806	// either fsync fails, the segment entry and the index record are rolled
807	// back and every batch stays staged with its reserved sequence; the
808	// error is ErrSyncFailed and retrying the group commits it without
809	// duplicating entries. A crash can never leave half of the group
810	// visible: the group is either wholly durable or wholly staged, and
811	// sequences reserved by a torn group stay permanent holes.
812	func (l *Log) CommitGroup(batches []Batch) ([]uint64, error) {
813		l.mu.Lock()
814		defer l.mu.Unlock()
815		if l.closed {
816			return nil, errClosed
817		}
818		if len(batches) == 0 {
819			return nil, nil
820		}
821		members := make([]groupMember, len(batches))
822		seqs := make([]uint64, len(batches))
823		seen := make(map[uint64]struct{}, len(batches))
824		for i, b := range batches {
825			recs, ok := l.staged[b.seq]
826			if !ok || b.owner != l {
827				return nil, ErrUnknownBatch
828			}
829			if _, dup := seen[b.seq]; dup {
830				return nil, ErrUnknownBatch
831			}
832			seen[b.seq] = struct{}{}
833			members[i] = groupMember{seq: b.seq, records: recs}
834			seqs[i] = b.seq
835		}
836		entry, offs, lens := encodeGroup(members)
837		idxBefore := l.idxSize
838		base, err := l.writeEntry(entry)
839		if err != nil {
840			return nil, err
841		}
842		if l.opts.Sync {
843			if err := syncFile(l.file); err != nil {
844				// Every batch stays staged and keeps its reserved sequence;
845				// a later CommitGroup retries. Drop the un-synced group
846				// entry so the retry cannot duplicate it.
847				l.rollbackEntry(base, idxBefore)
848				return nil, fmt.Errorf("%w: %v", ErrSyncFailed, err)
849			}
850		}
851		imembers := make([]indexMember, len(members))
852		for i, m := range members {
853			imembers[i] = indexMember{seq: m.seq, off: base + offs[i], length: lens[i]}
854		}
855		rec := encodeEntryRecord(indexEntry{
856			seg:     l.segIndex,
857			off:     base,
858			length:  len(entry),
859			diskCRC: binary.LittleEndian.Uint32(entry[len(entry)-4:]),
860			members: imembers,
861		})
862		if err := l.appendIndexRecord(rec); err != nil {
863			// The index never advertises a batch whose commit failed: roll
864			// both files back and leave the whole group staged for retry.
865			l.rollbackEntry(base, idxBefore)
866			return nil, err
867		}
868		first, last := seqs[0], seqs[0]
869		l.gen++
870		for i, m := range members {
871			delete(l.staged, m.seq)
872			l.index[m.seq] = entryRef{seg: l.segIndex, off: base + offs[i], length: lens[i], gen: l.gen}
873			if m.seq < first {
874				first = m.seq
875			}
876			if m.seq > last {
877				last = m.seq
878			}
879		}
880		l.commitSpan(first, last, len(members))
881		return seqs, nil
882	}
883	
884	// Read returns the records of the committed batch with the given
885	// sequence, located directly through the segment-level index. A staged
886	// but uncommitted sequence yields ErrNotCommitted; sequence 0,
887	// never-reserved sequences, and sequences beyond the reserved range
888	// yield ErrUnknownBatch.
889	//
890	// The lock is held only for the index lookup; the segment file is read
891	// and the body decoded without it, so a slow read never blocks writers.
892	func (l *Log) Read(seq uint64) ([][]byte, error) {
893		l.mu.RLock()
894		if l.closed {
895			l.mu.RUnlock()
896			return nil, errClosed
897		}
898		ref, ok := l.index[seq]
899		if !ok {
900			_, staged := l.staged[seq]
901			l.mu.RUnlock()
902			if staged {
903				return nil, ErrNotCommitted
904			}
905			return nil, ErrUnknownBatch
906		}
907		l.mu.RUnlock()
908		return l.readRef(seq, ref)
909	}
910	
911	// scanSnapshot is a read-consistent visibility boundary: a batch is
912	// visible only when its publication generation is <= gen and its
913	// sequence is <= highSeq. The boundary is captured in one brief
914	// read-lock acquisition, so a group that commits after a replay starts
915	// (even one filling an earlier reserved hole) is either wholly inside
916	// the snapshot or wholly outside it.
917	type scanSnapshot struct {
918		gen     uint64
919		highSeq uint64
920	}
921	
922	// Scan replays committed batches with sequence >= from in increasing
923	// sequence order, stopping at the first error returned by fn.
924	//
925	// The replay is a consistent snapshot: batches committed after the
926	// replay starts are invisible to it, and a group commit is seen either
927	// whole or not at all. The replay streams batches straight from the
928	// segment files one sequence at a time and keeps only the current
929	// batch in memory; it never loads the whole replay first. Each
930	// sequence lookup takes the lock briefly, while the file read, decode
931	// and the fn callback all run outside it, so a long replay never
932	// blocks writers.
933	func (l *Log) Scan(from uint64, fn func(Batch) error) error {
934		l.mu.RLock()
935		if l.closed {
936			l.mu.RUnlock()
937			return errClosed
938		}
939		snap := scanSnapshot{gen: l.gen, highSeq: l.nextSeq - 1}
940		l.mu.RUnlock()
941	
942		if from > snap.highSeq {
943			return nil
944		}
945		for seq := from; ; {
946			// One brief read-lock per sequence: only the index metadata is
947			// touched while holding it.
948			l.mu.RLock()
949			ref, ok := l.index[seq]
950			l.mu.RUnlock()
951			// Skip holes (reserved but uncommitted sequences) and batches
952			// published after the snapshot was taken.
953			if ok && ref.gen <= snap.gen {
954				records, err := l.readRef(seq, ref)
955				if err != nil {
956					return err
957				}
958				if err := fn(Batch{seq: seq, records: records, owner: l}); err != nil {
959					return err
960				}
961			}
962			if seq == snap.highSeq {
963				break
964			}
965			seq++
966		}
967		return nil
968	}
969	
970	// Segments lists the segments that hold committed batches, in file
971	// order, each with its first and last committed sequence.
972	func (l *Log) Segments() []Segment {
973		l.mu.RLock()
974		defer l.mu.RUnlock()
975		out := make([]Segment, len(l.segs))
976		copy(out, l.segs)
977		return out
978	}
979	
980	// Close closes the current segment file and the index sidecar. The log
981	// must not be used afterwards.
982	func (l *Log) Close() error {
983		l.mu.Lock()
984		defer l.mu.Unlock()
985		if l.closed {
986			return nil
987		}
988		l.closed = true
989		var err error
990		if l.file != nil {
991			err = l.file.Close()
992		}
993		if l.idxFile != nil {
994			if ierr := l.idxFile.Close(); err == nil {
995				err = ierr
996			}
997		}
998		return err
999	}
1000	
1001	// readRef loads the records of a committed batch straight from its
1002	// segment file. It performs no locking and must be called without l.mu
1003	// held: the segment read and body decode happen entirely on the read
1004	// path, outside the writer lock. The on-disk bytes are immutable once
1005	// committed (only the torn tail of the very last segment is ever
1006	// rewritten, and that tail never has an index entry), so a ref captured
1007	// under the read lock stays valid afterwards. The returned records are
1008	// freshly decoded, so callers can mutate them without affecting the
1009	// log or later reads.
1010	func (l *Log) readRef(seq uint64, ref entryRef) ([][]byte, error) {
1011		f, err := os.Open(l.segmentPath(ref.seg))
1012		if err != nil {
1013			return nil, err
1014		}
1015		defer f.Close()
1016		body := make([]byte, ref.length)
1017		if _, err := f.ReadAt(body, int64(ref.off)); err != nil {
1018			return nil, err
1019		}
1020		got, records, err := decodeBody(body)
1021		if err != nil {
1022			return nil, err
1023		}
1024		if got != seq {
1025			return nil, ErrCorruptSegment
1026		}
1027		return records, nil
1028	}
1029	
1030	// commitSpan records n newly committed batches covering sequences
1031	// [first, last] in the segment listing.
1032	func (l *Log) commitSpan(first, last uint64, n int) {
1033		if l.curBatches == 0 {
1034			l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
1035		} else {
1036			seg := &l.segs[len(l.segs)-1]
1037			if first < seg.FirstSeq {
1038				seg.FirstSeq = first
1039			}
1040			if last > seg.LastSeq {
1041				seg.LastSeq = last
1042			}
1043		}
1044		l.curBatches += n
1045	}
1046	
1047	// rollbackEntry undoes a commit that failed after its segment entry was
1048	// written: the segment file is truncated back to segOff and the just
1049	// appended index sidecar record back to idxSize. The batches involved
1050	// remain staged and a retry writes each entry exactly once.
1051	func (l *Log) rollbackEntry(segOff, idxSize int) {
1052		if l.file != nil {
1053			l.file.Truncate(int64(segOff))
1054			l.fileSize = segOff
1055		}
1056		l.truncateIndex(idxSize)
1057	}
1058	
1059	// rewriteTail drops a torn tail from segment n and, when the torn entry
1060	// carried recoverable sequences, replaces it with a synced hole marker
1061	// so the reserved sequences stay permanent holes across reopens.
1062	func (l *Log) rewriteTail(n, off int, seqs []uint64) error {
1063		path := l.segmentPath(n)
1064		if err := os.Truncate(path, int64(off)); err != nil {
1065			return err
1066		}
1067		keep := make([]uint64, 0, len(seqs))
1068		for _, seq := range seqs {
1069			if seq > 0 {
1070				keep = append(keep, seq)
1071			}
1072		}
1073		if len(keep) == 0 {
1074			return nil
1075		}
1076		f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0)
1077		if err != nil {
1078			return err
1079		}
1080		if _, err := f.Write(encodeHoles(keep)); err != nil {
1081			f.Close()
1082			return err
1083		}
1084		if err := f.Sync(); err != nil {
1085			f.Close()
1086			return err
1087		}
1088		return f.Close()
1089	}
1090	
1091	// writeEntry appends one encoded entry to the current segment, rolling
1092	// to a new segment when the current one is non-empty and would exceed
1093	// the configured capacity, and returns the offset the entry was
1094	// written at.
1095	func (l *Log) writeEntry(entry []byte) (int, error) {
1096		if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
1097			if err := l.file.Close(); err != nil {
1098				return 0, err
1099			}
1100			l.file = nil
1101			l.segIndex++
1102			l.curBatches = 0
1103		}
1104		if l.file == nil {
1105			if l.segIndex == 0 {
1106				l.segIndex = 1
1107			}
1108			if err := l.openCurrent(); err != nil {
1109				return 0, err
1110			}
1111		}
1112		off := l.fileSize
1113		n, err := l.file.Write(entry)
1114		if err != nil {
1115			return 0, err
1116		}
1117		l.fileSize += n
1118		return off, nil
1119	}
1120	
1121	func (l *Log) openCurrent() error {
1122		f, err := os.OpenFile(l.segmentPath(l.segIndex), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
1123		if err != nil {
1124			return err
1125		}
1126		st, err := f.Stat()
1127		if err != nil {
1128			f.Close()
1129			return err
1130		}
1131		l.file = f
1132		l.fileSize = int(st.Size())
1133		return nil
1134	}
1135	
1136	func (l *Log) segmentPath(index int) string {
1137		return filepath.Join(l.dir, fmt.Sprintf("%06d.seg", index))
1138	}
1139	
1140	// indexPath is the persistent index sidecar, one file per log directory.
1141	func (l *Log) indexPath() string {
1142		return filepath.Join(l.dir, "index.idx")
1143	}
1144	
1145	// syncDir fsyncs the log directory so a freshly renamed sidecar (or
1146	// created segment file) is durable itself. Best effort on filesystems
1147	// that cannot fsync directories.
1148	func syncDir(dir string) error {
1149		d, err := os.Open(dir)
1150		if err != nil {
1151			return err
1152		}
1153		err = d.Sync()
1154		if cerr := d.Close(); err == nil {
1155			err = cerr
1156		}
1157		return err
1158	}
1159	
1160	func copyRecords(records [][]byte) [][]byte {
1161		out := make([][]byte, len(records))
1162		for i, r := range records {
1163			cp := make([]byte, len(r))
1164			copy(cp, r)
1165			out[i] = cp
1166		}
1167		return out
1168	}
